// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1000, 560);

var BROWNS = ['#8a4b2d', '#c07a4e', '#e0a985', '#5e3220', '#a35c38', '#d99a6c', '#7a3b22', '#e8c1a5'];
var TEALS  = ['#2f7a6d', '#57a99a', '#8fcfc2', '#1f5a50', '#3e8f80', '#6dbfb0', '#a8dcd2', '#276b5f'];
var SLATE = '#3d4f63', EDGE_COL = '#3f6b72', NODE_STROKE = '#5e3220', ACCENT = '#ff9f1c';

/* Enlarged panel a: graph fills the left ~42% of the canvas */
var R = 24, NS = 15, ES = 13; // node radius, node-stack seg, edge-stack seg
var nodes = [ // x, y, stack offset (sx, sy = top of 5-seg stack)
  { x: 195, y: 80,  sx: 42,  sy: -78 }, // 1
  { x: 48,  y: 130, sx: 46,  sy: -70 }, // 2
  { x: 105, y: 305, sx: -64, sy: 10  }, // 3
  { x: 330, y: 100, sx: 44,  sy: -80 }, // 4
  { x: 385, y: 255, sx: 52,  sy: -20 }, // 5
  { x: 245, y: 470, sx: 46,  sy: 14  }  // 6
];
var edges = [[0,2],[0,3],[1,2],[2,3],[2,5],[3,4],[4,5]]; // 0-indexed pairs

var gA = draw.group(), gB = draw.group(), gC = draw.group(), gD = draw.group();
var hl = draw.group(); // highlight overlay, always on top

/* ---------- panel labels ---------- */
[['a)', 6, 26], ['b)', 432, 26], ['c)', 700, 26], ['d)', 432, 336]].forEach(function (p) {
  draw.text(p[0]).move(p[1], p[2]).font({ size: 22, family: 'serif' }).fill('#000');
});

/* ---------- panel a: graph ---------- */
var edgeLines = [], edgeStacks = [], nodeCircles = [], nodeStacks = [];

function edgeStackPos(j) {
  var e = edges[j], a = nodes[e[0]], b = nodes[e[1]];
  var mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
  var dx = b.x - a.x, dy = b.y - a.y, len = Math.sqrt(dx*dx + dy*dy);
  return { x: mx - dy / len * 26, y: my + dx / len * 26 };
}

edges.forEach(function (e, j) {
  var a = nodes[e[0]], b = nodes[e[1]];
  var ln = gA.line(a.x, a.y, b.x, b.y).stroke({ color: EDGE_COL, width: 3 });
  ln.css('cursor', 'pointer');
  ln.on('click', function () { selectEdge(j); });
  ln.on('mousemove', function (ev) { showTooltip('Edge ' + (e[0]+1) + '–' + (e[1]+1) + ' — click to locate it in A and E', ev); });
  ln.on('mouseleave', hideTooltip);
  edgeLines.push(ln);
  var p = edgeStackPos(j);
  var st = gA.group();
  for (var k = 0; k < 4; k++) {
    st.rect(ES, ES).move(p.x - ES / 2, p.y - 2 * ES + k * (ES + 1.5))
      .fill(TEALS[(j * 2 + k) % 8]).stroke({ color: '#555', width: 0.7 });
  }
  edgeStacks.push(st);
});

nodes.forEach(function (n, i) {
  var st = gA.group();
  for (var k = 0; k < 5; k++) {
    st.rect(NS, NS).move(n.x + n.sx, n.y + n.sy + k * (NS + 1.5))
      .fill(BROWNS[(i * 3 + k) % 8]).stroke({ color: '#555', width: 0.7 });
  }
  nodeStacks.push(st);
  var c = gA.circle(R * 2).center(n.x, n.y).fill('#fff').stroke({ color: NODE_STROKE, width: 3 });
  c.css('cursor', 'pointer');
  c.on('click', function () { selectNode(i); });
  c.on('mousemove', function (ev) { showTooltip('Node ' + (i+1) + ' — click to find its row/column of A and column of X', ev); });
  c.on('mouseleave', hideTooltip);
  nodeCircles.push(c);
  gA.text(String(i + 1)).center(n.x, n.y).font({ size: 19, family: 'serif' }).fill('#000');
});

/* ---------- panel b: adjacency matrix ---------- */
var aCells = [], AX = 500, AY = 150, AC = 28;
gB.text('Adjacency matrix, A').center(AX + 3 * AC, 62)
  .font({ size: 18, family: 'serif', style: 'italic' }).fill(SLATE);
gB.text('N × N').center(AX + 3 * AC, 88)
  .font({ size: 16, family: 'serif', style: 'italic' }).fill(SLATE);
var adj = {};
edges.forEach(function (e) { adj[e[0] + ',' + e[1]] = 1; adj[e[1] + ',' + e[0]] = 1; });
for (var i = 0; i < 6; i++) {
  aCells.push([]);
  gB.text(String(i + 1)).center(AX - 14, AY + i * AC + AC / 2).font({ size: 14, family: 'serif' });
  gB.text(String(i + 1)).center(AX + i * AC + AC / 2, AY - 16).font({ size: 14, family: 'serif' });
  for (var j = 0; j < 6; j++) {
    var filled = adj[i + ',' + j] ? 1 : 0;
    var r = gB.rect(AC - 3, AC - 3).move(AX + j * AC, AY + i * AC)
      .fill(filled ? SLATE : '#fff').stroke({ color: '#999', width: 1 });
    r.css('cursor', 'pointer');
    (function (ii, jj, f) {
      r.on('mousemove', function (ev) {
        showTooltip('A[' + (ii+1) + ',' + (jj+1) + '] = ' + f + (f ? ' — nodes ' + (ii+1) + ' and ' + (jj+1) + ' are connected' : ' — no edge'), ev);
      });
      r.on('mouseleave', hideTooltip);
      r.on('click', function () {
        showPopup('Adjacency matrix A', 'Cell (' + (ii+1) + ',' + (jj+1) + ') is ' + (f ? 'filled: an edge connects nodes ' + (ii+1) + ' and ' + (jj+1) + '. The matrix is symmetric because the graph is undirected.' : 'empty: those nodes are not directly connected.'));
      });
    })(i, j, filled);
    aCells[i].push(r);
  }
}

/* ---------- panel c: node data X ---------- */
var xCells = [], XX = 762, XY = 150, XC = 28;
gC.text('Node data, X').center(XX + 3 * XC, 54)
  .font({ size: 18, family: 'serif', style: 'italic' }).fill(NODE_STROKE);
gC.text('D × N').center(XX + 3 * XC, 80)
  .font({ size: 16, family: 'serif', style: 'italic' }).fill(NODE_STROKE);
for (var c2 = 0; c2 < 6; c2++) {
  gC.text(String(c2 + 1)).center(XX + c2 * XC + XC / 2, XY - 16).font({ size: 14, family: 'serif' });
  xCells.push([]);
  for (var r2 = 0; r2 < 4; r2++) {
    var xr = gC.rect(XC - 3, XC - 3).move(XX + c2 * XC, XY + r2 * XC)
      .fill(BROWNS[(c2 * 3 + r2) % 8]).stroke({ color: '#fff', width: 1 });
    xr.css('cursor', 'pointer');
    (function (cc) {
      xr.on('mousemove', function (ev) { showTooltip('Column ' + (cc+1) + ' of X = feature vector of node ' + (cc+1), ev); });
      xr.on('mouseleave', hideTooltip);
      xr.on('click', function () { selectNode(cc); });
    })(c2);
    xCells[c2].push(xr);
  }
}

/* ---------- panel d: edge data E (bottom-center, beneath panel b) ---------- */
var eCells = [], EX = 545, EY = 440, EC = 28;
gD.text('Edge data, E').move(432, 420)
  .font({ size: 18, family: 'serif', style: 'italic' }).fill('#2f7a6d');
gD.text('D_E × E').move(432, 446)
  .font({ size: 16, family: 'serif', style: 'italic' }).fill('#2f7a6d');
var eHeads = [];
edges.forEach(function (e, j) {
  var h1 = gD.text(String(e[0] + 1)).center(EX + j * EC + EC / 2, EY - 34).font({ size: 14, family: 'serif' });
  var h2 = gD.text(String(e[1] + 1)).center(EX + j * EC + EC / 2, EY - 14).font({ size: 14, family: 'serif' });
  eHeads.push([h1, h2]);
  eCells.push([]);
  for (var r3 = 0; r3 < 4; r3++) {
    var er = gD.rect(EC - 3, EC - 3).move(EX + j * EC, EY + r3 * EC)
      .fill(TEALS[(j * 2 + r3) % 8]).stroke({ color: '#fff', width: 1 });
    er.css('cursor', 'pointer');
    (function (jj) {
      er.on('mousemove', function (ev) {
        showTooltip('Column ' + (jj+1) + ' of E = features of edge ' + (edges[jj][0]+1) + '–' + (edges[jj][1]+1), ev);
      });
      er.on('mouseleave', hideTooltip);
      er.on('click', function () { selectEdge(jj); });
    })(j);
    eCells[j].push(er);
  }
});

/* ---------- selection logic ---------- */
function clearSelection() {
  hl.clear();
  nodeCircles.forEach(function (c) { c.stroke({ color: NODE_STROKE, width: 3 }); });
  edgeLines.forEach(function (l) { l.stroke({ color: EDGE_COL, width: 3 }); });
  eHeads.forEach(function (h) { h[0].fill('#000'); h[1].fill('#000'); });
}

function selectNode(i) {
  clearSelection();
  nodeCircles[i].stroke({ color: ACCENT, width: 5 });
  var n = nodes[i];
  hl.rect(NS + 4, 5 * (NS + 1.5) + 3).move(n.x + n.sx - 2, n.y + n.sy - 2).fill('none')
    .stroke({ color: ACCENT, width: 2.5 });
  for (var k = 0; k < 6; k++) {
    hl.rect(AC - 3, AC - 3).move(AX + k * AC, AY + i * AC)
      .fill(ACCENT).opacity(adj[i + ',' + k] ? 0.45 : 0.18);
    hl.rect(AC - 3, AC - 3).move(AX + i * AC, AY + k * AC)
      .fill(ACCENT).opacity(adj[k + ',' + i] ? 0.45 : 0.18);
  }
  for (var r = 0; r < 4; r++) {
    hl.rect(XC - 3, XC - 3).move(XX + i * XC, XY + r * XC).fill('none')
      .stroke({ color: ACCENT, width: 2.5 });
  }
  showPopup('Node ' + (i+1),
    'Node ' + (i+1) + ' owns row ' + (i+1) + ' AND column ' + (i+1) + ' of A — the filled cells list exactly its neighbors. Its attributes live in column ' + (i+1) + ' of X, the same brown stack drawn beside it in the graph.');
}

function selectEdge(j) {
  clearSelection();
  var e = edges[j], u = e[0], v = e[1];
  edgeLines[j].stroke({ color: ACCENT, width: 5 });
  var p = edgeStackPos(j);
  hl.rect(ES + 4, 4 * (ES + 1.5) + 2).move(p.x - ES / 2 - 2, p.y - 2 * ES - 2).fill('none')
    .stroke({ color: ACCENT, width: 2.5 });
  [[u, v], [v, u]].forEach(function (pr) {
    hl.rect(AC - 3, AC - 3).move(AX + pr[1] * AC, AY + pr[0] * AC).fill('none')
      .stroke({ color: ACCENT, width: 3 });
  });
  for (var r = 0; r < 4; r++) {
    hl.rect(EC - 3, EC - 3).move(EX + j * EC, EY + r * EC).fill('none')
      .stroke({ color: ACCENT, width: 2.5 });
  }
  eHeads[j][0].fill(ACCENT); eHeads[j][1].fill(ACCENT);
  showPopup('Edge ' + (u+1) + '–' + (v+1),
    'This undirected edge is stored twice in A — cells (' + (u+1) + ',' + (v+1) + ') and (' + (v+1) + ',' + (u+1) + ') — keeping A symmetric. Its teal feature vector is column ' + (j+1) + ' of E, the same stack drawn beside the edge.');
}

