    var er = gD.rect(EC - 3, EC - 3).move(EX + j * EC, EY + r3 * EC)
      .fill(TEALS[(j * 2 + r3) % 8]).stroke({ color: '#fff', width: 1 });
    er.css('cursor', 'pointer');
    (function (jj) {
      er.on('mousemove', function (ev) {
        showTooltip('Column ' + (jj+1) + ' of E = features of edge ' + (edges[jj][0]+1) + '–' + (edges[jj][1]+1), ev);
      });
      er.on('mouseleave', hideTooltip);
      er.on('click', function () { selectEdge(jj); });
    })(j);
    eCells[j].push(er);
  }
});

/* ---------- selection logic ---------- */
function clearSelection() {
  hl.clear();
  nodeCircles.forEach(function (c) { c.stroke({ color: NODE_STROKE, width: 3 }); });
  edgeLines.forEach(function (l) { l.stroke({ color: EDGE_COL, width: 3 }); });
  eHeads.forEach(function (h) { h[0].fill('#000'); h[1].fill('#000'); });
}

function selectNode(i) {
  clearSelection();
  nodeCircles[i].stroke({ color: ACCENT, width: 5 });
  var n = nodes[i];
  hl.rect(NS + 4, 5 * (NS + 1.5) + 3).move(n.x + n.sx - 2, n.y + n.sy - 2).fill('none')
    .stroke({ color: ACCENT, width: 2.5 });
  for (var k = 0; k < 6; k++) {
    hl.rect(AC - 3, AC - 3).move(AX + k * AC, AY + i * AC)
      .fill(ACCENT).opacity(adj[i + ',' + k] ? 0.45 : 0.18);
    hl.rect(AC - 3, AC - 3).move(AX + i * AC, AY + k * AC)
      .fill(ACCENT).opacity(adj[k + ',' + i] ? 0.45 : 0.18);
  }
  for (var r = 0; r < 4; r++) {
    hl.rect(XC - 3, XC - 3).move(XX + i * XC, XY + r * XC).fill('none')
      .stroke({ color: ACCENT, width: 2.5 });
  }
  showPopup('Node ' + (i+1),
    'Node ' + (i+1) + ' owns row ' + (i+1) + ' AND column ' + (i+1) + ' of A — the filled cells list exactly its neighbors. Its attributes live in column ' + (i+1) + ' of X, the same brown stack drawn beside it in the graph.');
}

function selectEdge(j) {
  clearSelection();
  var e = edges[j], u = e[0], v = e[1];
  edgeLines[j].stroke({ color: ACCENT, width: 5 });
  var p = edgeStackPos(j);
  hl.rect(ES + 4, 4 * (ES + 1.5) + 2).move(p.x - ES / 2 - 2, p.y - 2 * ES - 2).fill('none')
    .stroke({ color: ACCENT, width: 2.5 });
  [[u, v], [v, u]].forEach(function (pr) {
    hl.rect(AC - 3, AC - 3).move(AX + pr[1] * AC, AY + pr[0] * AC).fill('none')
      .stroke({ color: ACCENT, width: 3 });
  });
  for (var r = 0; r < 4; r++) {
    hl.rect(EC - 3, EC - 3).move(EX + j * EC, EY + r * EC).fill('none')
      .stroke({ color: ACCENT, width: 2.5 });
  }
  eHeads[j][0].fill(ACCENT); eHeads[j][1].fill(ACCENT);
  showPopup('Edge ' + (u+1) + '–' + (v+1),
    'This undirected edge is stored twice in A — cells (' + (u+1) + ',' + (v+1) + ') and (' + (v+1) + ',' + (u+1) + ') — keeping A symmetric. Its teal feature vector is column ' + (j+1) + ' of E, the same stack drawn beside the edge.');
}

/* ---------- focus toggle ---------- */
function toggle_focusPanel(val) {
  var map = { 'a) Graph': gA, 'b) Adjacency A': gB, 'c) Node data X': gC, 'd) Edge data E': gD };
  [gA, gB, gC, gD].forEach(function (g) { g.opacity(val === 'All panels' || map[val] === g ? 1 : 0.12); });
}

/* ---------- demo steps ---------- */
var steps = [
  { title: 'One graph, four views',
    narration: 'Panel a shows the graph as a picture: six nodes, seven edges, and a small colored feature stack attached to every node (brown) and every edge (teal). Panels b, c, and d store exactly the same information as matrices that a neural network can consume.',
    apply: function () { setFocusUI('All panels'); clearSelection(); } },
  { title: 'Click node 3',
    narration: 'Node 3 is the best-connected node. Its row and column light up in A (four filled cells = four neighbors: 1, 2, 4, 6), and column 3 of X lights up, matching the brown feature stack drawn beside it in the graph.',
    apply: function () { setFocusUI('All panels'); selectNode(2); } },
  { title: 'Click edge 3–4',
    narration: 'The edge between nodes 3 and 4 highlights two symmetric cells of A — (3,4) and (4,3) — because an undirected edge is recorded twice, and the column of E labeled 3 over 4 highlights, holding this edge\'s teal feature vector.',
    apply: function () { setFocusUI('All panels'); selectEdge(3); } },
  { title: 'Isolate each matrix',
    narration: 'Now only A is shown: alone it knows only who is connected. X alone knows only node attributes, E alone only edge attributes — cycle the focus toggle to verify; only together do they reconstruct panel a.',
    apply: function () { clearSelection(); setFocusUI('b) Adjacency A'); } }
];
var curStep = 0;
function setFocusUI(v) {
  document.getElementById('focusPanelInput').value = v;
  toggle_focusPanel(v);
}
function showStep(s) {
  curStep = Math.max(0, Math.min(steps.length - 1, s));
  steps[curStep].apply();
  document.getElementById('demoNarration').textContent = steps[curStep].narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length + ' — ' + steps[curStep].title;
}
function nextStep() { showStep(curStep + 1); }
function prevStep() { showStep(curStep - 1); }

showStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A graph with node and edge attributes is fully encoded by three matrices — the adjacency matrix A (connectivity), the node data matrix X (one feature column per node), and the edge data matrix E (one feature column per edge) — and every element of the visual graph maps to a specific location in each matrix.
KEY INSIGHT (what students should walk away understanding): Everything in the graph picture has an exact address in the matrices: a node is a row-plus-column of A and a column of X, and an edge is a symmetric pair of cells in A and a column of E — so A, X, and E together are a complete, machine-readable encoding of the graph.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A graph with node and edge attributes is fully encoded by three matrices — the adjacency matrix A (connectivity), the node data matrix X (one feature column per node), and the edge data matrix E (one feature column per edge) — and every element of the visual graph maps to a specific location in each matrix.",
  "figureType": "network_diagram",
  "elements": [
    "panel labels 'a)', 'b)', 'c)', 'd)'",
    "panel a: six node circles labeled 1–6 with dark brown outlines, arranged with node 2 upper-left, node 1 upper-center, node 4 upper-right-of-center, node 3 mid-left, node 5 right, node 6 bottom-center",
    "panel a: seven undirected teal edges: 1–3, 1–4, 2–3, 3–4, 3–6, 4–5, 5–6",
    "panel a: beside each node, a short vertical stack of small squares in brown/orange shades (that node's feature vector)",
    "panel a: beside each edge, a short vertical stack of small squares in teal/green shades (that edge's feature vector)",
    "panel b: title 'Adjacency matrix, A' with subtitle 'N × N' in dark slate blue",
    "panel b: 6×6 grid with row labels 1–6 (left) and column labels 1–6 (top); dark slate filled cells at (1,3),(1,4),(2,3),(3,1),(3,2),(3,4),(3,6),(4,1),(4,3),(4,5),(5,4),(5,6),(6,3),(6,5) — symmetric with empty diagonal",
    "panel c: title 'Node data, X' with subtitle 'D × N' in brown",
    "panel c: grid of 4 rows × 6 columns, column headers 1–6, cells in varied brown/orange shades matching each node's feature stack",
    "panel d: title 'Edge data, E' with subtitle 'D_E × E' in teal",
    "panel d: grid of 4 rows × 7 columns with two header rows giving edge endpoint pairs '1\\3', '1\\4', '2\\3', '3\\4', '3\\6', '4\\5', '5\\6', cells in varied teal/green shades matching each edge's feature stack"
  ],
  "interactions": [
    {
      "id": "selectNode",
